"""Different Ways to Add Parentheses — split at every operator, recurse.

Each operator can be the last one applied; combining every left result with
every right result enumerates all parenthesisations. Memoising on the substring
collapses the repeated work.

Time: O(Catalan(n))   Space: O(n^2) memo
"""
from functools import lru_cache
from typing import List


class Solution:
    def diffWaysToCompute(self, expression: str) -> List[int]:
        @lru_cache(maxsize=None)
        def solve(expr: str):
            if expr.isdigit():
                return (int(expr),)
            results = []
            for i, ch in enumerate(expr):
                if ch in "+-*":
                    for left in solve(expr[:i]):
                        for right in solve(expr[i + 1:]):
                            if ch == "+":
                                results.append(left + right)
                            elif ch == "-":
                                results.append(left - right)
                            else:
                                results.append(left * right)
            return tuple(results)

        return list(solve(expression))
